content.content:
     1→/* ===== Reset & Base ===== */
     2→*, *::before, *::after {
     3→  box-sizing: border-box;
     4→  margin: 0;
     5→  padding: 0;
     6→}
     7→
     8→:root {
     9→  --bg:           #1a1a2e;
    10→  --bg-2:         #16213e;
    11→  --bg-3:         #0f3460;
    12→  --accent:       #e94560;
    13→  --accent-glow:  rgba(233, 69, 96, 0.4);
    14→  --accent-2:     #533483;
    15→  --text:         #e0e0f0;
    16→  --text-muted:   #8888aa;
    17→  --surface:      rgba(255, 255, 255, 0.06);
    18→  --surface-hover: rgba(255, 255, 255, 0.10);
    19→  --border:       rgba(255, 255, 255, 0.08);
    20→  --radius:       16px;
    21→  --radius-sm:    10px;
    22→  --transition:   0.2s ease;
    23→  --mic-size:     88px;
    24→  --ring-size:    128px;
    25→}
    26→
    27→html, body {
    28→  height: 100%;
    29→  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
    30→  background: var(--bg);
    31→  color: var(--text);
    32→  -webkit-font-smoothing: antialiased;
    33→  -webkit-tap-highlight-color: transparent;
    34→  overscroll-behavior: none;
    35→}
    36→
    37→#app {
    38→  display: flex;
    39→  flex-direction: column;
    40→  height: 100dvh;
    41→  max-width: 480px;
    42→  margin: 0 auto;
    43→  position: relative;
    44→}
    45→
    46→/* ===== Header ===== */
    47→.header {
    48→  display: flex;
    49→  align-items: center;
    50→  justify-content: space-between;
    51→  padding: 16px 20px 12px;
    52→  background: linear-gradient(180deg, var(--bg) 0%, transparent 100%);
    53→  position: relative;
    54→  z-index: 10;
    55→  flex-shrink: 0;
    56→}
    57→
    58→.header-title {
    59→  display: flex;
    60→  align-items: center;
    61→  gap: 10px;
    62→}
    63→
    64→.logo-dot {
    65→  width: 10px;
    66→  height: 10px;
    67→  background: var(--accent);
    68→  border-radius: 50%;
    69→  box-shadow: 0 0 8px var(--accent-glow);
    70→  animation: pulse-dot 3s ease-in-out infinite;
    71→  flex-shrink: 0;
    72→}
    73→
    74→@keyframes pulse-dot {
    75→  0%, 100% { opacity: 1; transform: scale(1); }
    76→  50%       { opacity: 0.6; transform: scale(0.85); }
    77→}
    78→
    79→.header h1 {
    80→  font-size: 1.25rem;
    81→  font-weight: 700;
    82→  letter-spacing: 0.03em;
    83→  color: var(--text);
    84→}
    85→
    86→.header-actions {
    87→  display: flex;
    88→  align-items: center;
    89→  gap: 8px;
    90→}
    91→
    92→
    93→.icon-btn {
    94→  background: var(--surface);
    95→  border: 1px solid var(--border);
    96→  color: var(--text-muted);
    97→  border-radius: 50%;
    98→  width: 44px;
    99→  height: 44px;
   100→  display: flex;
   101→  align-items: center;
   102→  justify-content: center;
   103→  cursor: pointer;
   104→  transition: background var(--transition), color var(--transition);
   105→}
   106→
   107→.icon-btn svg {
   108→  width: 18px;
   109→  height: 18px;
   110→}
   111→
   112→.icon-btn:hover, .icon-btn:focus-visible {
   113→  background: var(--surface-hover);
   114→  color: var(--text);
   115→  outline: none;
   116→}
   117→
   118→/* ===== Messages ===== */
   119→.messages {
   120→  flex: 1;
   121→  overflow-y: auto;
   122→  padding: 12px 20px;
   123→  display: flex;
   124→  flex-direction: column;
   125→  gap: 10px;
   126→  -webkit-overflow-scrolling: touch;
   127→  scrollbar-width: thin;
   128→  scrollbar-color: var(--border) transparent;
   129→}
   130→
   131→.messages::-webkit-scrollbar       { width: 4px; }
   132→.messages::-webkit-scrollbar-track { background: transparent; }
   133→.messages::-webkit-scrollbar-thumb { background: var(--border); border-radius: 2px; }
   134→
   135→.messages-empty {
   136→  flex: 1;
   137→  display: flex;
   138→  align-items: center;
   139→  justify-content: center;
   140→}
   141→
   142→.messages-empty p {
   143→  color: var(--text-muted);
   144→  font-size: 0.9rem;
   145→  text-align: center;
   146→}
   147→
   148→/* Message bubble */
   149→.message {
   150→  background: var(--surface);
   151→  border: 1px solid var(--border);
   152→  border-radius: var(--radius);
   153→  border-bottom-right-radius: 4px;
   154→  padding: 12px 16px;
   155→  max-width: 100%;
   156→  word-break: break-word;
   157→  animation: slide-up 0.25s ease both;
   158→}
   159→
   160→.message.sending       { opacity: 0.6; }
   161→.message.sent          { border-color: rgba(233, 69, 96, 0.2); }
   162→.message.error         { border-color: rgba(255, 80, 80, 0.3); }
   163→
   164→.message-text {
   165→  font-size: 0.95rem;
   166→  line-height: 1.5;
   167→  color: var(--text);
   168→}
   169→
   170→.message-meta {
   171→  display: flex;
   172→  align-items: center;
   173→  gap: 8px;
   174→  margin-top: 6px;
   175→}
   176→
   177→.message-time {
   178→  font-size: 0.75rem;
   179→  color: var(--text-muted);
   180→}
   181→
   182→.message-status {
   183→  font-size: 0.72rem;
   184→  padding: 2px 7px;
   185→  border-radius: 20px;
   186→  background: var(--surface);
   187→  color: var(--text-muted);
   188→}
   189→
   190→.message.sent .message-status {
   191→  background: rgba(233, 69, 96, 0.15);
   192→  color: var(--accent);
   193→}
   194→
   195→.message.error .message-status {
   196→  background: rgba(255, 80, 80, 0.15);
   197→  color: #ff6b6b;
   198→}
   199→
   200→@keyframes slide-up {
   201→  from { opacity: 0; transform: translateY(12px); }
   202→  to   { opacity: 1; transform: translateY(0); }
   203→}
   204→
   205→/* ===== Live Transcript ===== */
   206→.live-transcript {
   207→  margin: 0 20px 8px;
   208→  background: var(--surface);
   209→  border: 1px solid var(--border);
   210→  border-radius: var(--radius);
   211→  padding: 14px 16px;
   212→  animation: fade-in 0.2s ease;
   213→}
   214→
   215→.live-transcript p {
   216→  font-size: 0.92rem;
   217→  color: var(--text-muted);
   218→  font-style: italic;
   219→  line-height: 1.5;
   220→  min-height: 1.4em;
   221→}
   222→
   223→.live-transcript p.has-text {
   224→  color: var(--text);
   225→  font-style: normal;
   226→}
   227→
   228→/* Auto-scroll in brainstorm mode */
   229→.live-transcript.brainstorm-mode {
   230→  max-height: 130px;
   231→  overflow-y: auto;
   232→  scroll-behavior: smooth;
   233→}
   234→
   235→/* ===== Transcript Bar (post-recording) ===== */
   236→.transcript-bar {
   237→  margin: 0 20px 12px;
   238→  background: var(--bg-2);
   239→  border: 1px solid var(--border);
   240→  border-radius: var(--radius);
   241→  padding: 16px;
   242→  animation: slide-up 0.2s ease;
   243→}
   244→
   245→.transcript-text {
   246→  font-size: 0.95rem;
   247→  line-height: 1.5;
   248→  color: var(--text);
   249→  margin-bottom: 14px;
   250→  word-break: break-word;
   251→}
   252→
   253→.transcript-actions {
   254→  display: flex;
   255→  gap: 10px;
   256→  justify-content: flex-end;
   257→}
   258→
   259→/* ===== Buttons ===== */
   260→.btn-ghost {
   261→  background: transparent;
   262→  border: 1px solid var(--border);
   263→  color: var(--text-muted);
   264→  border-radius: var(--radius-sm);
   265→  padding: 8px 18px;
   266→  font-size: 0.9rem;
   267→  cursor: pointer;
   268→  transition: all var(--transition);
   269→}
   270→
   271→.btn-ghost:hover, .btn-ghost:focus-visible {
   272→  background: var(--surface);
   273→  color: var(--text);
   274→  outline: none;
   275→}
   276→
   277→.btn-send {
   278→  background: var(--accent);
   279→  border: none;
   280→  color: #fff;
   281→  border-radius: var(--radius-sm);
   282→  padding: 8px 22px;
   283→  font-size: 0.9rem;
   284→  font-weight: 600;
   285→  cursor: pointer;
   286→  transition: all var(--transition);
   287→  box-shadow: 0 2px 12px rgba(233, 69, 96, 0.35);
   288→}
   289→
   290→.btn-send:hover, .btn-send:focus-visible {
   291→  background: #ff5c75;
   292→  outline: none;
   293→  box-shadow: 0 4px 20px rgba(233, 69, 96, 0.55);
   294→}
   295→
   296→.btn-send:disabled {
   297→  opacity: 0.45;
   298→  cursor: not-allowed;
   299→  box-shadow: none;
   300→}
   301→
   302→/* ===== Mic Section ===== */
   303→.mic-section {
   304→  flex-shrink: 0;
   305→  display: flex;
   306→  flex-direction: column;
   307→  align-items: center;
   308→  padding: 16px 20px 36px;
   309→  gap: 16px;
   310→}
   311→
   312→.mic-hint {
   313→  font-size: 0.85rem;
   314→  color: var(--text-muted);
   315→  letter-spacing: 0.04em;
   316→  transition: color var(--transition);
   317→  min-height: 1.2em;
   318→  text-align: center;
   319→}
   320→
   321→.mic-hint.active           { color: var(--accent); }
   322→.mic-hint.brainstorm-active { color: rgba(163, 121, 221, 1); }
   323→.mic-hint.processing       { color: var(--text-muted); font-style: italic; }
   324→
   325→/* Dual-mode button container */
   326→.mic-buttons {
   327→  display: flex;
   328→  align-items: flex-start;
   329→  justify-content: center;
   330→  gap: 28px;
   331→}
   332→
   333→.mode-btn-wrap {
   334→  display: flex;
   335→  flex-direction: column;
   336→  align-items: center;
   337→  gap: 8px;
   338→}
   339→
   340→.mode-label {
   341→  font-size: 0.72rem;
   342→  font-weight: 700;
   343→  letter-spacing: 0.08em;
   344→  text-transform: uppercase;
   345→  color: var(--text-muted);
   346→  transition: color var(--transition);
   347→}
   348→
   349→.mode-label.brainstorm-label {
   350→  color: rgba(163, 121, 221, 0.7);
   351→}
   352→
   353→/* Brainstorm meta: timer + replay + WS dot */
   354→.brainstorm-meta {
   355→  display: flex;
   356→  align-items: center;
   357→  justify-content: center;
   358→  gap: 6px;
   359→  min-height: 24px;
   360→}
   361→
   362→/* Timer */
   363→.timer-text {
   364→  font-size: 0.75rem;
   365→  color: var(--text-muted);
   366→  font-family: 'SF Mono', 'Fira Code', ui-monospace, monospace;
   367→  letter-spacing: 0.04em;
   368→  min-width: 36px;
   369→  text-align: center;
   370→}
   371→
   372→/* Replay controls wrapper */
   373→.replay-controls {
   374→  display: flex;
   375→  align-items: center;
   376→  gap: 4px;
   377→}
   378→
   379→/* Replay (play/pause) button */
   380→.replay-btn {
   381→  width: 44px;
   382→  height: 44px;
   383→  border-radius: 50%;
   384→  background: var(--surface);
   385→  border: 1px solid var(--border);
   386→  color: var(--text-muted);
   387→  cursor: pointer;
   388→  display: flex;
   389→  align-items: center;
   390→  justify-content: center;
   391→  transition: background var(--transition), color var(--transition),
   392→              border-color var(--transition), box-shadow var(--transition);
   393→  flex-shrink: 0;
   394→}
   395→
   396→.replay-btn .replay-icon {
   397→  width: 14px;
   398→  height: 14px;
   399→  display: block;
   400→}
   401→
   402→.replay-btn:hover:not(:disabled) {
   403→  background: var(--surface-hover);
   404→  color: var(--text);
   405→}
   406→
   407→.replay-btn:focus-visible {
   408→  outline: 2px solid var(--accent);
   409→  outline-offset: 2px;
   410→}
   411→
   412→.replay-btn:disabled {
   413→  opacity: 0.28;
   414→  cursor: not-allowed;
   415→}
   416→
   417→/* "Has recording" state — slightly brighter when a recording is available */
   418→.replay-btn[data-state="available"]:not(:disabled) {
   419→  color: rgba(163, 121, 221, 0.8);
   420→  border-color: rgba(163, 121, 221, 0.3);
   421→}
   422→
   423→.replay-btn[data-state="available"]:hover:not(:disabled) {
   424→  background: rgba(163, 121, 221, 0.12);
   425→  color: rgba(163, 121, 221, 1);
   426→  border-color: rgba(163, 121, 221, 0.5);
   427→}
   428→
   429→/* Playing state */
   430→.replay-btn.replay-playing {
   431→  color: rgba(163, 121, 221, 1);
   432→  border-color: rgba(163, 121, 221, 0.5);
   433→  background: rgba(163, 121, 221, 0.12);
   434→  box-shadow: 0 0 0 3px rgba(163, 121, 221, 0.15);
   435→  animation: replay-pulse 1.8s ease-in-out infinite;
   436→}
   437→
   438→@keyframes replay-pulse {
   439→  0%, 100% { box-shadow: 0 0 0 3px rgba(163, 121, 221, 0.15); }
   440→  50%       { box-shadow: 0 0 0 5px rgba(163, 121, 221, 0.28); }
   441→}
   442→
   443→/* Stop button */
   444→.stop-btn {
   445→  width: 32px;
   446→  height: 32px;
   447→  border-radius: 50%;
   448→  background: var(--surface);
   449→  border: 1px solid var(--border);
   450→  color: var(--text-muted);
   451→  cursor: pointer;
   452→  display: flex;
   453→  align-items: center;
   454→  justify-content: center;
   455→  transition: background var(--transition), color var(--transition),
   456→              opacity var(--transition);
   457→  flex-shrink: 0;
   458→  animation: fade-in 0.15s ease;
   459→}
   460→
   461→.stop-btn svg {
   462→  width: 11px;
   463→  height: 11px;
   464→}
   465→
   466→.stop-btn:hover {
   467→  background: var(--surface-hover);
   468→  color: var(--accent);
   469→  border-color: rgba(233, 69, 96, 0.3);
   470→}
   471→
   472→.stop-btn:focus-visible {
   473→  outline: 2px solid var(--accent);
   474→  outline-offset: 2px;
   475→}
   476→
   477→/* Progress bar under brainstorm meta */
   478→.replay-progress-wrap {
   479→  width: 100%;
   480→  padding: 0 4px;
   481→  animation: fade-in 0.2s ease;
   482→}
   483→
   484→.replay-progress-track {
   485→  height: 3px;
   486→  background: var(--border);
   487→  border-radius: 2px;
   488→  overflow: hidden;
   489→}
   490→
   491→.replay-progress-fill {
   492→  height: 100%;
   493→  width: 0%;
   494→  background: linear-gradient(90deg, rgba(163, 121, 221, 0.7), rgba(163, 121, 221, 1));
   495→  border-radius: 2px;
   496→  transition: width 0.1s linear;
   497→}
   498→
   499→/* WebSocket status dot */
   500→.ws-dot {
   501→  width: 7px;
   502→  height: 7px;
   503→  border-radius: 50%;
   504→  background: #ff3b30;
   505→  transition: background-color 0.3s ease;
   506→  flex-shrink: 0;
   507→}
   508→
   509→.ws-dot.connected  { background: #34c759; }
   510→.ws-dot.idle       { background: rgba(163, 121, 221, 0.8); }
   511→.ws-dot.connecting { background: #ff9500; animation: blink 1s ease-in-out infinite; }
   512→
   513→/* Shrink buttons slightly for side-by-side layout */
   514→.mic-buttons .mic-ring {
   515→  width: 112px;
   516→  height: 112px;
   517→}
   518→
   519→.mic-buttons .mic-btn {
   520→  width: 76px;
   521→  height: 76px;
   522→}
   523→
   524→.mic-buttons .mic-icon {
   525→  width: 30px;
   526→  height: 30px;
   527→}
   528→
   529→/* Ring / glow around button */
   530→.mic-ring {
   531→  position: relative;
   532→  width: var(--ring-size);
   533→  height: var(--ring-size);
   534→  display: flex;
   535→  align-items: center;
   536→  justify-content: center;
   537→}
   538→
   539→.mic-ring::before,
   540→.mic-ring::after {
   541→  content: '';
   542→  position: absolute;
   543→  inset: 0;
   544→  border-radius: 50%;
   545→  border: 2px solid transparent;
   546→  transition: all 0.3s ease;
   547→}
   548→
   549→.mic-ring.recording::before {
   550→  border-color: var(--accent-glow);
   551→  animation: ring-pulse 1.4s ease-in-out infinite;
   552→}
   553→
   554→.mic-ring.recording::after {
   555→  border-color: rgba(233, 69, 96, 0.15);
   556→  animation: ring-pulse 1.4s ease-in-out 0.7s infinite;
   557→}
   558→
   559→@keyframes ring-pulse {
   560→  0%   { transform: scale(1); opacity: 1; }
   561→  100% { transform: scale(1.6); opacity: 0; }
   562→}
   563→
   564→/* The mic button */
   565→.mic-btn {
   566→  position: relative;
   567→  width: var(--mic-size);
   568→  height: var(--mic-size);
   569→  border-radius: 50%;
   570→  border: none;
   571→  background: linear-gradient(145deg, var(--bg-3), var(--accent-2));
   572→  color: #fff;
   573→  cursor: pointer;
   574→  display: flex;
   575→  align-items: center;
   576→  justify-content: center;
   577→  box-shadow:
   578→    0 4px 24px rgba(0, 0, 0, 0.4),
   579→    0 0 0 1px rgba(255, 255, 255, 0.08);
   580→  transition: transform 0.15s ease, box-shadow 0.15s ease, opacity 0.15s ease;
   581→  -webkit-user-select: none;
   582→  user-select: none;
   583→  touch-action: manipulation;
   584→  z-index: 1;
   585→}
   586→
   587→.mic-btn:hover {
   588→  transform: scale(1.05);
   589→  box-shadow:
   590→    0 6px 32px rgba(0, 0, 0, 0.5),
   591→    0 0 0 1px rgba(255, 255, 255, 0.12);
   592→}
   593→
   594→.mic-btn:active  { transform: scale(0.96); }
   595→
   596→.mic-btn:focus-visible {
   597→  outline: 2px solid var(--accent);
   598→  outline-offset: 4px;
   599→}
   600→
   601→.mic-btn:disabled {
   602→  opacity: 0.4;
   603→  cursor: not-allowed;
   604→  transform: none !important;
   605→}
   606→
   607→.mic-btn.recording {
   608→  background: linear-gradient(145deg, var(--accent), #c0392b);
   609→  box-shadow:
   610→    0 4px 32px var(--accent-glow),
   611→    0 0 0 1px rgba(233, 69, 96, 0.3);
   612→  animation: mic-glow 1.4s ease-in-out infinite alternate;
   613→}
   614→
   615→@keyframes mic-glow {
   616→  from { box-shadow: 0 4px 24px var(--accent-glow), 0 0 0 1px rgba(233, 69, 96, 0.3); }
   617→  to   { box-shadow: 0 4px 48px rgba(233, 69, 96, 0.7), 0 0 0 1px rgba(233, 69, 96, 0.5); }
   618→}
   619→
   620→.mic-icon {
   621→  width: 36px;
   622→  height: 36px;
   623→  transition: transform var(--transition);
   624→}
   625→
   626→.mic-btn.recording .mic-icon { transform: scale(1.1); }
   627→
   628→/* ===== Brainstorm button colour overrides ===== */
   629→.mic-btn.brainstorm-btn {
   630→  background: linear-gradient(145deg, var(--bg-3), var(--accent-2));
   631→}
   632→
   633→.mic-btn.brainstorm-btn:hover {
   634→  transform: scale(1.05);
   635→}
   636→
   637→.mic-btn.brainstorm-btn.recording {
   638→  background: linear-gradient(145deg, var(--accent-2), #7b2fbe);
   639→  box-shadow:
   640→    0 4px 32px rgba(83, 52, 131, 0.55),
   641→    0 0 0 1px rgba(163, 121, 221, 0.35);
   642→  animation: brainstorm-glow 1.4s ease-in-out infinite alternate;
   643→}
   644→
   645→@keyframes brainstorm-glow {
   646→  from { box-shadow: 0 4px 24px rgba(83, 52, 131, 0.4),  0 0 0 1px rgba(163, 121, 221, 0.3); }
   647→  to   { box-shadow: 0 4px 48px rgba(83, 52, 131, 0.75), 0 0 0 1px rgba(163, 121, 221, 0.55); }
   648→}
   649→
   650→/* Brainstorm ring pulses in purple when recording */
   651→.mic-ring.brainstorm-ring.recording::before {
   652→  border-color: rgba(163, 121, 221, 0.55);
   653→}
   654→
   655→.mic-ring.brainstorm-ring.recording::after {
   656→  border-color: rgba(163, 121, 221, 0.2);
   657→}
   658→
   659→/* ===== Not supported ===== */
