   685→.modal-overlay[hidden] { display: none; }
   686→
   687→.modal {
   688→  background: var(--bg-2);
   689→  border: 1px solid var(--border);
   690→  border-radius: var(--radius) var(--radius) 0 0;
   691→  width: 100%;
   692→  max-width: 480px;
   693→  animation: slide-modal 0.3s cubic-bezier(0.4, 0, 0.2, 1);
