   722→  flex-direction: column;
   723→  gap: 8px;
   724→}
   725→
   726→.modal-body label {
   727→  font-size: 0.85rem;
   728→  color: var(--text-muted);
   729→  font-weight: 500;
   730→  margin-top: 4px;
   731→}
   732→
   733→.modal-body input,
   734→.modal-body select {
   735→  background: var(--surface);
   736→  border: 1px solid var(--border);
   737→  border-radius: var(--radius-sm);
   738→  color: var(--text);
   739→  font-size: 0.95rem;
   740→  padding: 12px 14px;
   741→  width: 100%;
