   790→
   791→/* ===== Keyframes ===== */
   792→@keyframes fade-in {
   793→  from { opacity: 0; }
   794→  to   { opacity: 1; }
   795→}
   796→
   797→@keyframes blink {
   798→  0%, 100% { opacity: 1; }
   799→  50%       { opacity: 0.4; }
   800→}
   801→
   802→@keyframes spin {
