   819→
   820→/* ===== Wake word indicator ===== */
   821→.wake-dot {
   822→  width: 8px;
   823→  height: 8px;
   824→  border-radius: 50%;
   825→  background: #34c759;
   826→  box-shadow: 0 0 6px rgba(52, 199, 89, 0.55);
